   \filldraw[black] (D) circle (2pt) node[above right]{$Q$};
    \filldraw[black] (O) circle (2pt) node[below left] {$O$};
    \filldraw[black] (P) circle (2pt) node[above right] {$E$};
     \filldraw[black] (Q) circle (2pt) node[above left] {$F$};
      \filldraw[black] (M) circle (2pt) node[above left] {$I$};
     \filldraw[black] (N) circle (2pt) node[above right] {$J$};
